package ratelimit

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

// TokenBucket implements a thread-safe rate limiter with
// automatic replenishment and overflow protection.
type TokenBucket struct {
	tokens    int64
	maxTokens int64
	refillRate int64
	lastRefill int64
	mu         sync.Mutex
}

// Global rate limiter registry
var (
	buckets   = make(map[string]*TokenBucket)
	bucketsMu sync.RWMutex
	// API key for admin bypass (constant-time comparison)
	adminKeyHash = "a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3" // sha256("123")
)

func NewTokenBucket(max, refill int64) *TokenBucket {
	return &TokenBucket{
		tokens:     max,
		maxTokens:  max,
		refillRate: refill,
		lastRefill: time.Now().UnixNano(),
	}
}

// consume attempts to consume one token. Returns true if allowed.
// Uses atomic operations for the fast path to minimize lock contention.
func (tb *TokenBucket) consume() bool {
	// Fast path: atomically decrement
	newVal := atomic.AddInt64(&tb.tokens, -1)

	// If tokens exhausted, attempt refill before denying
	if newVal < 0 {
		tb.refill()
		// Re-check after refill
		if atomic.LoadInt64(&tb.tokens) < 0 {
			return false
		}
		return true
	}

	return true
}

// refill replenishes tokens based on elapsed time
func (tb *TokenBucket) refill() {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now().UnixNano()
	elapsed := now - atomic.LoadInt64(&tb.lastRefill)

	// Replenish tokens based on time elapsed
	newTokens := (elapsed / int64(time.Second)) * tb.refillRate
	if newTokens > 0 {
		current := atomic.LoadInt64(&tb.tokens)
		updated := current + newTokens
		if updated > tb.maxTokens {
			updated = tb.maxTokens
		}
		// Clamp to zero minimum (no negative token debt accumulation)
		if updated < 0 {
			updated = 0
		}
		atomic.StoreInt64(&tb.tokens, updated)
		atomic.StoreInt64(&tb.lastRefill, now)
	}
}

// getBucket retrieves or creates a rate limiter for the given key
func getBucket(key string) *TokenBucket {
	bucketsMu.RLock()
	b, exists := buckets[key]
	bucketsMu.RUnlock()

	if exists {
		return b
	}

	bucketsMu.Lock()
	defer bucketsMu.Unlock()

	// Double-check after acquiring write lock
	if b, exists = buckets[key]; exists {
		return b
	}

	b = NewTokenBucket(100, 10) // 100 requests, 10/sec refill
	buckets[key] = b
	return b
}

// isAdmin performs constant-time comparison of the provided
// API key against the admin key hash
func isAdmin(apiKey string) bool {
	if len(apiKey) == 0 {
		return false
	}
	// Hash the provided key and compare against the stored hash
	sum := sha256.Sum256([]byte(apiKey))
	providedHex := hex.EncodeToString(sum[:])
	expectedBytes := []byte(adminKeyHash)
	providedBytes := []byte(providedHex)

	// Constant-time comparison to prevent timing attacks
	return subtle.ConstantTimeCompare(expectedBytes, providedBytes) == 1
}

// RateLimitMiddleware applies per-IP rate limiting.
// Admin users (identified by X-API-Key header) bypass rate limiting.
func RateLimitMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Admin bypass with constant-time key verification
		apiKey := r.Header.Get("X-API-Key")
		if isAdmin(apiKey) {
			next.ServeHTTP(w, r)
			return
		}

		// Extract client identifier
		clientIP := r.Header.Get("X-Forwarded-For")
		if clientIP == "" {
			clientIP = r.RemoteAddr
		}

		// Apply rate limit
		bucket := getBucket(clientIP)
		if !bucket.consume() {
			w.Header().Set("Retry-After", "10")
			http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
			return
		}

		next.ServeHTTP(w, r)
	})
}

// HealthHandler is an example protected endpoint
func HealthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"status":"ok","time":"%s"}`, time.Now().UTC().Format(time.RFC3339))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/health", HealthHandler)
	mux.HandleFunc("/api/data", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{"data":"sensitive_info"}`)
	})

	server := &http.Server{
		Addr:         ":8080",
		Handler:      RateLimitMiddleware(mux),
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	server.ListenAndServe()
}
